use std::env;
use std::fs;
use std::path::{Component, Path};
use std::process::{Command, Output};

// Exercise APT's real acquire method with the source stanza generated by CI.
// No package is installed, and no global APT lists or archives are written.
#[test]
fn apt_rejects_a_changed_transitive_package_with_its_signed_byte_length() {
    let root = env::current_dir().unwrap().join("artifacts/zenoh-ci-apt");
    let local = root.join("integrity-test");
    fs::create_dir(&local).unwrap();
    for dir in ["lists/partial", "archives/partial"] {
        fs::create_dir_all(local.join(dir)).unwrap();
    }
    let source = fs::read_to_string(root.join("sources.list.d/ubuntu.sources")).unwrap();
    let source = source.replace(root.to_str().unwrap(), local.to_str().unwrap());
    fs::write(local.join("fixture.sources"), source).unwrap();
    fs::write(
        local.join("mirrors"),
        format!(
            "file:{}/repo/\ttype:index\ncopy:{}/\ttype:deb\n",
            root.display(),
            local.display(),
        ),
    )
    .unwrap();
    let run = |program: &str, args: &[&str]| {
        let mut cmd = Command::new(program);
        cmd.env("LC_ALL", "C").current_dir(&local);
        for (key, value) in [
            ("Dir::Etc::sourcelist", "fixture.sources"),
            ("Dir::State::lists", "lists"),
            ("Dir::Cache::archives", "archives"),
        ] {
            cmd.arg("-o")
                .arg(format!("{key}={}", local.join(value).display()));
        }
        cmd.args([
            "-o",
            "Dir::Etc::sourceparts=-",
            "-o",
            "Dir::Cache::pkgcache=",
            "-o",
            "Dir::Cache::srcpkgcache=",
            "-o",
            "Acquire::Languages=none",
            "-o",
            "Acquire::CompressionTypes::Order=xz",
        ]);
        cmd.args(args).output().unwrap()
    };
    let assert_success = |output: Output| {
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
        String::from_utf8(output.stdout).unwrap()
    };
    assert_success(run("apt-get", &["--error-on=any", "update"]));
    let records = assert_success(run("apt-cache", &["show", "libfmt-dev"]));
    let record = records
        .split("\n\n")
        .find(|row| row.lines().any(|line| line.starts_with("Filename: ")))
        .expect("an available transitive package in the signed snapshot");
    let field = |name: &str| record.lines().find_map(|l| l.strip_prefix(name)).unwrap();
    let filename = Path::new(field("Filename: "));
    assert!(
        filename.starts_with("pool")
            && filename
                .components()
                .all(|c| matches!(c, Component::Normal(_)))
    );
    let size = field("Size: ").parse::<u64>().unwrap();
    assert!(size > 0);
    let wrong = local.join(filename);
    fs::create_dir_all(wrong.parent().unwrap()).unwrap();
    fs::File::create(wrong).unwrap().set_len(size).unwrap();
    let pin = format!("libfmt-dev={}", field("Version: "));
    let bad = run("apt-get", &["download", &pin]);
    assert!(!bad.status.success());
    let error = String::from_utf8(bad.stderr).unwrap();
    assert!(
        error.contains("Hash Sum mismatch") && error.contains(field("SHA256: ")),
        "{error}"
    );
    fs::remove_dir_all(local).unwrap();
}
